package com.pillar; import org.junit.jupiter.api.*; import javax.crypto.*; import javax.crypto.spec.*; import java.util.*; public class WebhookTest { static String sign(byte[] p,long ts)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec("whsec".getBytes(),"HmacSHA256"));m.update((ts+".").getBytes());return "t="+ts+",v1="+HexFormat.of().formatHex(m.doFinal(p));} @Test void verifiesRawBody() throws Exception{byte[] raw="{\"b\":2,\"id\":\"evt_1\"}".getBytes();String h=sign(raw,System.currentTimeMillis()/1000); Assertions.assertEquals("evt_1", Webhook.constructEvent(raw,h,"whsec",300).get("id")); Assertions.assertThrows(IllegalArgumentException.class,()->Webhook.constructEvent("{\"id\":\"evt_1\",\"b\":2}".getBytes(),h,"whsec",300));} }
